import numpy as np

def capture(fn, *args):
    try:
        fn(*args)
        return 0.0
    except ValueError:
        return 1.0
    except Exception:
        return 2.0

coeffs = np.array([
    0.9489489489489491,
    0.4633103691927221,
    0.2752191290298749,
    0.7207207207207207,
    0.3358980541217181,
    0.5259259259259259,
    0.8715294886755629
], dtype=float)

def derivative_error(fn):
    h = 1e-5
    cp = coeffs.copy()
    cm = coeffs.copy()
    cp[5] *= np.exp(-h)
    cm[5] *= np.exp(h)
    fd = (
        fn(cp, 1.4, 1.1)[0]
        - fn(cm, 1.4, 1.1)[0]
    )/(2*h)
    return abs(fn(coeffs, 1.4, 1.1)[1] - fd)
assert np.allclose(derivative_error(compute_fraction_sensitivity), target)

